package xyz.peppie.versatilelogger;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import xyz.peppie.versatilelogger.VersatileLoggerPlugin;

public class VersatileLoggerTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(VersatileLoggerPlugin.class);
		RuneLite.main(args);
	}
}

package xyz.peppie.versatilelogger.io.remote;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import xyz.peppie.versatilelogger.dto.DiscordContentPayload;
import xyz.peppie.versatilelogger.dto.FullMessagePayload;

/**
 * Sends formatted messages to a user-configured remote HTTP endpoint. Every send goes through a
 * per-destination-URL {@link DestinationQueue}, drained at a fixed interval on a single
 * background thread, so this plugin never hammers a destination (e.g. a Discord webhook, subject
 * to its own rate limits) regardless of local chat volume. All network I/O happens via
 * {@link OkHttpClient#newCall(Request)}'s async {@code enqueue}, never on the client thread.
 */
@Slf4j
@Singleton
public class RemoteLogSender
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final long DRAIN_INTERVAL_MS = 500;
	private static final int MAX_QUEUE_SIZE = 50;

	private final OkHttpClient okHttpClient;
	private final Gson gson;
	private final Map<String, DestinationQueue> destinations = new ConcurrentHashMap<>();
	private volatile ScheduledExecutorService scheduler;

	@Inject
	RemoteLogSender(OkHttpClient okHttpClient, Gson gson)
	{
		this.okHttpClient = okHttpClient;
		this.gson = gson;
	}

	public void startUp()
	{
		scheduler = Executors.newSingleThreadScheduledExecutor();
	}

	public void shutDown()
	{
		destinations.values().forEach(DestinationQueue::cancel);
		destinations.clear();
		if (scheduler != null)
		{
			scheduler.shutdownNow();
			scheduler = null;
		}
	}

	public void sendInGameMessage(String url, String authTokenOrNull, String line)
	{
		enqueue(url, authTokenOrNull, new DiscordContentPayload(line));
	}

	public void sendFull(String url, String authTokenOrNull, FullMessagePayload payload)
	{
		enqueue(url, authTokenOrNull, payload);
	}

	private void enqueue(String url, String authTokenOrNull, Object body)
	{
		if (scheduler == null || url == null || url.isBlank())
		{
			return;
		}

		RequestBody requestBody = RequestBody.create(JSON, gson.toJson(body));
		Request.Builder builder = new Request.Builder()
			.url(url)
			.post(requestBody);
		if (authTokenOrNull != null && !authTokenOrNull.isBlank())
		{
			builder.header("Authorization", "Bearer " + authTokenOrNull);
		}

		DestinationQueue queue = destinations.computeIfAbsent(url, this::createDestination);
		queue.offer(builder.build());
	}

	private DestinationQueue createDestination(String url)
	{
		DestinationQueue queue = new DestinationQueue(MAX_QUEUE_SIZE);
		ScheduledFuture<?> drainTask = scheduler.scheduleAtFixedRate(
			() -> drain(queue), DRAIN_INTERVAL_MS, DRAIN_INTERVAL_MS, TimeUnit.MILLISECONDS);
		queue.setDrainTask(drainTask);
		return queue;
	}

	private void drain(DestinationQueue queue)
	{
		Request request = queue.poll();
		if (request == null)
		{
			return;
		}

		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Remote log request failed", e);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				if (!response.isSuccessful())
				{
					log.debug("Remote log request returned HTTP {}", response.code());
				}
				response.body().close();
			}
		});
	}
}

package xyz.peppie.versatilelogger.io.remote;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.concurrent.ScheduledFuture;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Request;

/**
 * Bounded, drop-oldest-on-overflow outbound queue for one remote destination URL. Draining
 * happens on a shared {@link java.util.concurrent.ScheduledExecutorService} owned by
 * {@link RemoteLogSender}, at a fixed interval, so a single busy destination can't be hammered
 * faster than that interval regardless of how quickly messages are enqueued.
 */
@Slf4j
class DestinationQueue
{
	private final Deque<Request> queue = new ArrayDeque<>();
	private final int maxSize;
	private ScheduledFuture<?> drainTask;

	DestinationQueue(int maxSize)
	{
		this.maxSize = maxSize;
	}

	synchronized void offer(Request request)
	{
		if (queue.size() >= maxSize)
		{
			queue.pollFirst();
			log.debug("Remote log destination queue full, dropping oldest queued request");
		}
		queue.addLast(request);
	}

	synchronized Request poll()
	{
		return queue.pollFirst();
	}

	void setDrainTask(ScheduledFuture<?> drainTask)
	{
		this.drainTask = drainTask;
	}

	void cancel()
	{
		if (drainTask != null)
		{
			drainTask.cancel(false);
		}
	}
}

package xyz.peppie.versatilelogger.io.local;

import java.io.IOException;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class LogRetentionManager
{
	private static final DateTimeFormatter SESSION_STAMP =
		DateTimeFormatter.ofPattern("yyyy-MM-dd_HH-mm-ss");
	private static final int STAMP_LENGTH = "yyyy-MM-dd_HH-mm-ss".length();

	public void run(Path root, int retentionDays)
	{
		if (retentionDays <= 0 || !Files.isDirectory(root))
		{
			return;
		}

		LocalDateTime cutoff = LocalDateTime.now().minusDays(retentionDays);

		try (DirectoryStream<Path> accounts = Files.newDirectoryStream(root))
		{
			for (Path accountDir : accounts)
			{
				if (Files.isDirectory(accountDir))
				{
					cleanAccountDir(accountDir, cutoff);
				}
			}
		}
		catch (IOException e)
		{
			log.debug("Failed to walk log root for retention cleanup", e);
		}
	}

	private void cleanAccountDir(Path accountDir, LocalDateTime cutoff)
	{
		try (DirectoryStream<Path> entries = Files.newDirectoryStream(accountDir))
		{
			for (Path entry : entries)
			{
				if (Files.isDirectory(entry))
				{
					cleanCategoryDir(entry, cutoff);
				}
				else
				{
					deleteIfStale(entry, cutoff);
				}
			}
		}
		catch (IOException e)
		{
			log.debug("Failed to walk account dir for retention cleanup: {}", accountDir, e);
		}
	}

	private void cleanCategoryDir(Path categoryDir, LocalDateTime cutoff)
	{
		boolean anyLeft = false;
		try (DirectoryStream<Path> entries = Files.newDirectoryStream(categoryDir))
		{
			for (Path entry : entries)
			{
				if (!deleteIfStale(entry, cutoff))
				{
					anyLeft = true;
				}
			}
		}
		catch (IOException e)
		{
			log.debug("Failed to walk category dir for retention cleanup: {}", categoryDir, e);
			return;
		}

		if (!anyLeft)
		{
			try
			{
				Files.deleteIfExists(categoryDir);
			}
			catch (IOException e)
			{
				log.debug("Failed to prune empty category dir: {}", categoryDir, e);
			}
		}
	}

	private boolean deleteIfStale(Path file, LocalDateTime cutoff)
	{
		LocalDateTime stamp = parseStamp(file.getFileName().toString());
		if (stamp == null || !stamp.isBefore(cutoff))
		{
			return false;
		}

		if (!isSafeToDelete(file))
		{
			log.debug("Refusing to delete path outside plugin root: {}", file);
			return false;
		}

		try
		{
			Files.deleteIfExists(file);
			log.debug("Deleted stale log file: {}", file);
			return true;
		}
		catch (IOException e)
		{
			log.debug("Failed to delete stale log file: {}", file, e);
			return false;
		}
	}

	private static boolean isSafeToDelete(Path file)
	{
		Path normalized = file.toAbsolutePath().normalize();
		Path root = LocalLogWriter.PLUGIN_ROOT.toAbsolutePath().normalize();
		return normalized.startsWith(root);
	}

	private static LocalDateTime parseStamp(String filename)
	{
		if (filename.length() < STAMP_LENGTH)
		{
			return null;
		}
		try
		{
			return LocalDateTime.parse(filename.substring(0, STAMP_LENGTH), SESSION_STAMP);
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}
}

package xyz.peppie.versatilelogger.io.local;

import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import xyz.peppie.versatilelogger.chat.ChatCategory;

@Slf4j
@Singleton
public class LocalLogWriter
{
	public static final Path PLUGIN_ROOT = RuneLite.RUNELITE_DIR.toPath().resolve("versatile-logger");

	private static final DateTimeFormatter SESSION_STAMP =
		DateTimeFormatter.ofPattern("yyyy-MM-dd_HH-mm-ss");

	private volatile ExecutorService executor;

	// Only ever accessed from tasks running on `executor`.
	private final Map<ChatCategory, BufferedWriter> perCategoryWriters = new HashMap<>();
	private BufferedWriter singleFileWriter;
	private Path accountDir;
	private boolean perCategoryFiles;
	private String sessionStamp;

	public void startUp(ExecutorService executor)
	{
		this.executor = executor;
	}

	public void beginSession(String accountName, boolean perCategoryFiles)
	{
		if (executor == null)
		{
			return;
		}
		String stamp = SESSION_STAMP.format(LocalDateTime.now());
		executor.execute(() ->
		{
			closeAll();
			this.accountDir = PLUGIN_ROOT.resolve(sanitizeFolderName(accountName));
			this.perCategoryFiles = perCategoryFiles;
			this.sessionStamp = stamp;
			log.debug("Local log session started for {}", accountDir);
		});
	}

	public void writeLine(ChatCategory category, String line)
	{
		if (executor == null)
		{
			return;
		}
		executor.execute(() -> doWrite(category, line));
	}

	public void endSession()
	{
		if (executor == null)
		{
			return;
		}
		executor.execute(this::closeAll);
	}

	private void doWrite(ChatCategory category, String line)
	{
		if (accountDir == null)
		{
			log.debug("Dropping local log line for {}, no session started yet", category);
			return;
		}
		try
		{
			BufferedWriter writer = perCategoryFiles ? perCategoryWriter(category) : singleFileWriter();
			writer.write(line);
			writer.newLine();
			writer.flush();
		}
		catch (IOException e)
		{
			log.debug("Failed to write local log line for category {}", category, e);
		}
	}

	private BufferedWriter perCategoryWriter(ChatCategory category) throws IOException
	{
		BufferedWriter writer = perCategoryWriters.get(category);
		if (writer != null)
		{
			return writer;
		}

		Path categoryDir = accountDir.resolve(category.getFolderSlug());
		Files.createDirectories(categoryDir);
		Path file = categoryDir.resolve(sessionStamp + "-" + category.getFolderSlug() + "_log.txt");
		writer = Files.newBufferedWriter(file, StandardCharsets.UTF_8,
			StandardOpenOption.CREATE, StandardOpenOption.APPEND);
		perCategoryWriters.put(category, writer);
		return writer;
	}

	private BufferedWriter singleFileWriter() throws IOException
	{
		if (singleFileWriter != null)
		{
			return singleFileWriter;
		}

		Files.createDirectories(accountDir);
		Path file = accountDir.resolve(sessionStamp + ".txt");
		singleFileWriter = Files.newBufferedWriter(file, StandardCharsets.UTF_8,
			StandardOpenOption.CREATE, StandardOpenOption.APPEND);
		return singleFileWriter;
	}

	private void closeAll()
	{
		perCategoryWriters.values().forEach(this::closeQuietly);
		perCategoryWriters.clear();
		closeQuietly(singleFileWriter);
		singleFileWriter = null;
		accountDir = null;
	}

	private void closeQuietly(BufferedWriter writer)
	{
		if (writer == null)
		{
			return;
		}
		try
		{
			writer.close();
		}
		catch (IOException e)
		{
			log.debug("Failed to close local log writer", e);
		}
	}

	private static String sanitizeFolderName(String name)
	{
		return name == null ? "unknown" : name.replaceAll("[\\\\/:*?\"<>|]", "_");
	}
}

package xyz.peppie.versatilelogger.chat;

import java.util.EnumSet;
import java.util.Set;
import lombok.Getter;
import net.runelite.api.ChatMessageType;

@Getter
public enum ChatCategory
{
	PUBLIC_CHAT("Public chat", "public-chat",
		EnumSet.of(ChatMessageType.PUBLICCHAT, ChatMessageType.MODCHAT)),
	CHANNEL_CHAT("Channel chat (friends chat)", "channel-chat",
		EnumSet.of(ChatMessageType.FRIENDSCHAT)),
	CLAN_CHAT("Clan chat", "clan-chat",
		EnumSet.of(ChatMessageType.CLAN_CHAT)),
	GAME_MESSAGES("Game messages", "game-messages",
		EnumSet.of(ChatMessageType.GAMEMESSAGE, ChatMessageType.ENGINE, ChatMessageType.WELCOME,
			ChatMessageType.BROADCAST, ChatMessageType.DIDYOUKNOW, ChatMessageType.FRIENDSCHATNOTIFICATION,
			ChatMessageType.CLAN_MESSAGE, ChatMessageType.CLAN_GUEST_MESSAGE)),
	PRIVATE_MESSAGES("Private messages", "private-messages",
		EnumSet.of(ChatMessageType.PRIVATECHAT, ChatMessageType.PRIVATECHATOUT)),
	GUEST_CLAN_CHAT("Guest clan chat", "guest-clan-chat",
		EnumSet.of(ChatMessageType.CLAN_GUEST_CHAT)),
	GROUP_CHAT("Group chat (Group Ironman)", "group-chat",
		EnumSet.of(ChatMessageType.CLAN_GIM_CHAT, ChatMessageType.CLAN_GIM_FORM_GROUP,
			ChatMessageType.CLAN_GIM_GROUP_WITH, ChatMessageType.CLAN_GIM_MESSAGE)),
	COLLECTION_LOG("Collection log unlock", "collection-log", EnumSet.noneOf(ChatMessageType.class)),
	HIGH_VALUE_DROP("High value drop", "high-value-drop", EnumSet.noneOf(ChatMessageType.class)),
	PET_DROP("Pet drops", "pet-drop", EnumSet.noneOf(ChatMessageType.class)),
	LEVEL_UP("Level up", "level-up", EnumSet.of(ChatMessageType.LEVELUPMESSAGE));

	private final String displayName;
	private final String folderSlug;
	private final Set<ChatMessageType> types;

	ChatCategory(String displayName, String folderSlug, Set<ChatMessageType> types)
	{
		this.displayName = displayName;
		this.folderSlug = folderSlug;
		this.types = types;
	}
}

package xyz.peppie.versatilelogger.chat;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.FriendsChatManager;
import net.runelite.api.FriendsChatMember;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanChannelMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.util.Text;
import xyz.peppie.versatilelogger.dto.ClanChatDto;
import xyz.peppie.versatilelogger.dto.ClanRankDto;
import xyz.peppie.versatilelogger.dto.FriendsChatDto;
import xyz.peppie.versatilelogger.dto.MessageDto;
import xyz.peppie.versatilelogger.dto.UserDto;
import xyz.peppie.versatilelogger.format.MessageFormatter;

@Singleton
public class ClanContextResolver
{
	private final Client client;

	@Inject
	ClanContextResolver(Client client)
	{
		this.client = client;
	}

	public MessageDto buildMessage(MessageNode node, boolean edited)
	{
		return new MessageDto(node.getId(), node.getTimestamp(), node.getType().name(),
			MessageFormatter.resolvedValue(node), edited);
	}

	public UserDto buildUser(MessageNode node, ChatMessageType type)
	{
		String senderName = resolveSenderName(node, type);
		int ironmanType = client.getVarbitValue(VarbitID.IRONMAN);
		ClanRankDto clanRank = resolveClanRank(senderName);
		String friendsChatRank = resolveFriendsChatRank(senderName);
		return new UserDto(senderName, ironmanType, clanRank, friendsChatRank);
	}

	/**
	 * For outgoing private messages, {@link MessageNode#getName()} holds the recipient, not the
	 * local player - the game never rewrites it to the sender for that message type. Everywhere
	 * else, getName() is already the account that actually sent the message.
	 */
	private String resolveSenderName(MessageNode node, ChatMessageType type)
	{
		if (type == ChatMessageType.PRIVATECHATOUT)
		{
			Player localPlayer = client.getLocalPlayer();
			if (localPlayer != null && localPlayer.getName() != null)
			{
				return localPlayer.getName();
			}
		}
		return node.getName();
	}

	public ClanChatDto buildClanChat(ChatMessageType type)
	{
		if (type == ChatMessageType.CLAN_CHAT || type == ChatMessageType.CLAN_MESSAGE)
		{
			ClanChannel channel = client.getClanChannel();
			return channel == null ? null : new ClanChatDto(channel.getName());
		}
		if (type == ChatMessageType.CLAN_GUEST_CHAT)
		{
			ClanChannel channel = client.getGuestClanChannel();
			return channel == null ? null : new ClanChatDto(channel.getName());
		}
		return null;
	}

	public FriendsChatDto buildFriendsChat(ChatMessageType type)
	{
		if (type != ChatMessageType.FRIENDSCHAT)
		{
			return null;
		}
		FriendsChatManager manager = client.getFriendsChatManager();
		return manager == null ? null : new FriendsChatDto(manager.getName(), manager.getOwner());
	}

	private ClanRankDto resolveClanRank(String senderName)
	{
		if (senderName == null || senderName.isBlank())
		{
			return null;
		}
		String sanitized = Text.sanitize(senderName);

		ClanChannel primary = client.getClanChannel();
		ClanChannelMember member = primary == null ? null : primary.findMember(sanitized);
		if (member != null)
		{
			return toClanRankDto(member.getRank(), client.getClanSettings());
		}

		ClanChannel guest = client.getGuestClanChannel();
		member = guest == null ? null : guest.findMember(sanitized);
		if (member != null)
		{
			return new ClanRankDto(member.getRank().getRank(), null);
		}

		return null;
	}

	private static ClanRankDto toClanRankDto(ClanRank rank, ClanSettings settings)
	{
		String title = null;
		if (settings != null)
		{
			ClanTitle clanTitle = settings.titleForRank(rank);
			title = clanTitle == null ? null : clanTitle.getName();
		}
		return new ClanRankDto(rank.getRank(), title);
	}

	private String resolveFriendsChatRank(String senderName)
	{
		if (senderName == null || senderName.isBlank())
		{
			return null;
		}
		FriendsChatManager manager = client.getFriendsChatManager();
		if (manager == null)
		{
			return null;
		}
		FriendsChatMember member = manager.findByName(Text.sanitize(senderName));
		return member == null ? null : member.getRank().name();
	}
}

package xyz.peppie.versatilelogger.chat;

import java.util.regex.Pattern;

final class ClanBroadcastPatterns
{
	private static final Pattern DROP_PATTERN =
		Pattern.compile(".*received (a(?: rare)? drop|special loot from a raid): .*", Pattern.DOTALL);

	private static final Pattern LEVEL_MILESTONE_PATTERN =
		Pattern.compile(".* has reached (a |the highest possible )?[^<>]+? level( of)? [\\d,]+[!.].*", Pattern.DOTALL);

	private ClanBroadcastPatterns() {	}

	static boolean isLevelUpOrDropBroadcast(String message)
	{
		if (message == null)
		{
			return false;
		}

		return DROP_PATTERN.matcher(message).matches() || LEVEL_MILESTONE_PATTERN.matcher(message).matches();
	}
}

package xyz.peppie.versatilelogger.chat;

import java.util.EnumSet;
import java.util.Set;

import xyz.peppie.versatilelogger.config.VersatileLoggerConfig;
import xyz.peppie.versatilelogger.config.VersatileLoggerConfig.FormatMode;
import xyz.peppie.versatilelogger.config.VersatileLoggerConfig.IncludeOptionBasic;
import xyz.peppie.versatilelogger.config.VersatileLoggerConfig.IncludeOptionBasicCommand;
import xyz.peppie.versatilelogger.config.VersatileLoggerConfig.IncludeOptionClanChat;
import xyz.peppie.versatilelogger.config.VersatileLoggerConfig.IncludeOptionClanChatCommand;
import xyz.peppie.versatilelogger.config.VersatileLoggerConfig.IncludeOptionFriendsChat;
import xyz.peppie.versatilelogger.config.VersatileLoggerConfig.IncludeOptionGroupChat;
import xyz.peppie.versatilelogger.format.LineIncludeOption;

/**
 * Maps a {@link ChatCategory} to its category-specific config accessors and normalizes whichever
 * of the config-facing include enums applies into the category-agnostic {@link LineIncludeOption}
 * set the formatter (and the plugin's command-output tracking) consumes. Deliberately a plain
 * switch (no reflection) since AGENTS.md forbids reflection.
 */
public class CategoryConfigResolver
{
	public CategorySettings resolve(VersatileLoggerConfig config, ChatCategory category)
	{
		boolean globalRemote = config.remoteLoggingEnabled();
		String globalUrl = config.remoteUrl();
		FormatMode globalFormat = config.formatMode();

		switch (category)
		{
			case PUBLIC_CHAT:
				return build(config.publicChatLocalEnabled(), globalRemote && config.publicChatRemoteEnabled(),
					config.publicChatOverrideUrlEnabled(), config.publicChatOverrideUrl(), globalUrl,
					config.publicChatOverrideFormatEnabled(), config.publicChatOverrideFormat(), globalFormat,
					config.publicChatDetailedTimestamp(), toLineOptionsBasicCommand(config.publicChatInclude()));
			case CHANNEL_CHAT:
				return build(config.channelChatLocalEnabled(), globalRemote && config.channelChatRemoteEnabled(),
					config.channelChatOverrideUrlEnabled(), config.channelChatOverrideUrl(), globalUrl,
					config.channelChatOverrideFormatEnabled(), config.channelChatOverrideFormat(), globalFormat,
					config.channelChatDetailedTimestamp(), toLineOptionsFriendsChat(config.channelChatInclude()));
			case CLAN_CHAT:
				return build(config.clanChatLocalEnabled(), globalRemote && config.clanChatRemoteEnabled(),
					config.clanChatOverrideUrlEnabled(), config.clanChatOverrideUrl(), globalUrl,
					config.clanChatOverrideFormatEnabled(), config.clanChatOverrideFormat(), globalFormat,
					config.clanChatDetailedTimestamp(), toLineOptionsClanChatCommand(config.clanChatInclude()));
			case GAME_MESSAGES:
				return build(config.gameMessagesLocalEnabled(), globalRemote && config.gameMessagesRemoteEnabled(),
					config.gameMessagesOverrideUrlEnabled(), config.gameMessagesOverrideUrl(), globalUrl,
					config.gameMessagesOverrideFormatEnabled(), config.gameMessagesOverrideFormat(), globalFormat,
					config.gameMessagesDetailedTimestamp(), toLineOptions(config.gameMessagesInclude()));
			case PRIVATE_MESSAGES:
				return build(config.privateMessagesLocalEnabled(), globalRemote && config.privateMessagesRemoteEnabled(),
					config.privateMessagesOverrideUrlEnabled(), config.privateMessagesOverrideUrl(), globalUrl,
					config.privateMessagesOverrideFormatEnabled(), config.privateMessagesOverrideFormat(), globalFormat,
					config.privateMessagesDetailedTimestamp(), toLineOptionsBasicCommand(config.privateMessagesInclude()));
			case GUEST_CLAN_CHAT:
				return build(config.guestClanChatLocalEnabled(), globalRemote && config.guestClanChatRemoteEnabled(),
					config.guestClanChatOverrideUrlEnabled(), config.guestClanChatOverrideUrl(), globalUrl,
					config.guestClanChatOverrideFormatEnabled(), config.guestClanChatOverrideFormat(), globalFormat,
					config.guestClanChatDetailedTimestamp(), toLineOptionsClanChat(config.guestClanChatInclude()));
			case GROUP_CHAT:
				return build(config.groupChatLocalEnabled(), globalRemote && config.groupChatRemoteEnabled(),
					config.groupChatOverrideUrlEnabled(), config.groupChatOverrideUrl(), globalUrl,
					config.groupChatOverrideFormatEnabled(), config.groupChatOverrideFormat(), globalFormat,
					config.groupChatDetailedTimestamp(), toLineOptionsGroupChat(config.groupChatInclude()));
			case COLLECTION_LOG:
				return build(config.collectionLogLocalEnabled(), globalRemote && config.collectionLogRemoteEnabled(),
					config.collectionLogOverrideUrlEnabled(), config.collectionLogOverrideUrl(), globalUrl,
					config.collectionLogOverrideFormatEnabled(), config.collectionLogOverrideFormat(), globalFormat,
					config.collectionLogDetailedTimestamp(), toLineOptions(config.collectionLogInclude()));
			case HIGH_VALUE_DROP:
				return build(config.highValueDropLocalEnabled(), globalRemote && config.highValueDropRemoteEnabled(),
					config.highValueDropOverrideUrlEnabled(), config.highValueDropOverrideUrl(), globalUrl,
					config.highValueDropOverrideFormatEnabled(), config.highValueDropOverrideFormat(), globalFormat,
					config.highValueDropDetailedTimestamp(), toLineOptions(config.highValueDropInclude()));
			case PET_DROP:
				return build(config.petDropLocalEnabled(), globalRemote && config.petDropRemoteEnabled(),
					config.petDropOverrideUrlEnabled(), config.petDropOverrideUrl(), globalUrl,
					config.petDropOverrideFormatEnabled(), config.petDropOverrideFormat(), globalFormat,
					config.petDropDetailedTimestamp(), toLineOptions(config.petDropInclude()));
			case LEVEL_UP:
				return build(config.levelUpLocalEnabled(), globalRemote && config.levelUpRemoteEnabled(),
					config.levelUpOverrideUrlEnabled(), config.levelUpOverrideUrl(), globalUrl,
					config.levelUpOverrideFormatEnabled(), config.levelUpOverrideFormat(), globalFormat,
					config.levelUpDetailedTimestamp(), toLineOptions(config.levelUpInclude()));
			default:
				throw new IllegalArgumentException("Unhandled category: " + category);
		}
	}

	private static CategorySettings build(boolean localEnabled, boolean remoteEnabled,
		boolean overrideUrlEnabled, String overrideUrl, String globalUrl,
		boolean overrideFormatEnabled, FormatMode overrideFormat, FormatMode globalFormat,
		boolean detailedTimestamp, Set<LineIncludeOption> include)
	{
		String effectiveUrl = overrideUrlEnabled && overrideUrl != null && !overrideUrl.isBlank()
			? overrideUrl
			: globalUrl;
		FormatMode effectiveFormat = overrideFormatEnabled ? overrideFormat : globalFormat;
		return new CategorySettings(localEnabled, remoteEnabled, effectiveUrl, effectiveFormat, detailedTimestamp, include);
	}

	private static Set<LineIncludeOption> toLineOptions(Set<IncludeOptionBasic> include)
	{
		Set<LineIncludeOption> result = EnumSet.noneOf(LineIncludeOption.class);
		if (include.contains(IncludeOptionBasic.TIMESTAMP))
		{
			result.add(LineIncludeOption.TIMESTAMP);
		}
		if (include.contains(IncludeOptionBasic.ICONS))
		{
			result.add(LineIncludeOption.ICONS);
		}
		return result;
	}

